import type { DocumentContent } from "../documents";

const content = {
    html: resolveAssets("<h1 id=\"types\">Types</h1><p>Destack extends TypeScript&#39;s type system with precise primitives, nominal types (&quot;<code>newtype</code>s&quot;), value types (&quot;<code>struct</code>s&quot;), tuples, <code>where</code>-based constraints, and some additional niceties.</p>\n<h2 id=\"primitives\">Primitives</h2><p>Destack is based on TypeScript, and TypeScript inherits its main primitive types from JavaScript: <code>string</code>, <code>boolean</code>, <code>number</code>, <code>bigint</code>, and <code>symbol</code>, plus the <code>null</code> and <code>undefined</code> sentinels.\nDestack evolves this set into a serious set of primitive types:</p>\n<ul>\n<li>precise numeric types beyond <code>number</code>, with variable-width signed and unsigned integers (<code>int8</code>, <code>uint32</code>, <code>int17</code>) as well as concrete float formats (<code>float16</code>, <code>float32</code>, <code>float64</code>)</li>\n<li>pointer-sized integers, i.e. integers as wide as the target pointer size, spelled <code>isize</code> and <code>usize</code></li>\n<li><code>int</code> and <code>uint</code> as aliases to <code>int64</code> and <code>uint64</code></li>\n<li><code>number</code> becomes an alias for <code>float</code>, and <code>float</code> becomes an alias for <code>float64</code></li>\n<li><code>char</code> as a single Unicode scalar value, distinct from <code>string</code></li>\n</ul>\n<p>It should be noted that <code>string</code> and <code>bigint</code> are not really &quot;special&quot; in Destack like they are in TypeScript, they are just aliases to the standard library <code>String</code> and <code>BigInt</code> classes.\nThey feel the same, though.\nIn general, Destack follows TypeScript behavior as exactly as possible for a sound and strict type system, including the exact same widening rules where numeric literals start as exact values and can flow into any numeric type that can represent them.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Primitives</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint64</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">12345</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"literal\">7</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint3</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"literal\">7</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint2</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: 7 does not fit uint2</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">exact</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">42</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"name\">exact</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">int64</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">balance</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">100.50</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"name\">balance</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">float64</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">n</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">1.0</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"name\">n</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">float</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">initial</span><span data-k=\"punct\">:</span> <span data-k=\"type\">char</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">'A'</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">input</span><span data-k=\"punct\">:</span> <span data-k=\"type\">unknown</span> <span data-k=\"punct\">=</span> <span data-k=\"function\">readInput</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h2 id=\"unknown\">Unknown</h2><p>TypeScript has two &quot;top&quot; types: <code>unknown</code> and <code>any</code> can contain <em>all</em> other types.\nOf course, <code>any</code> is unsound, because everything can be assigned to and from <code>any</code> without any checks, so Destack forbids it in favor of the explicit <code>unknown</code>.\n<code>unknown</code> is really just a transparent constraint, and so it behaves like an interface with zero members under the regular <a href=\"#representation\">representation rules</a>:</p>\n<ul>\n<li>In constraint positions, <code>unknown</code> induces an implicit generic: <code>function parse(value: unknown)</code> behaves like <code>function parse&lt;T&gt;(value: T)</code> where the body knows nothing about <code>T</code> until it narrows.</li>\n<li>In storage positions, bare <code>unknown</code> has no layout, so it must either induce a generic parameter or be erased behind <code>Dynamic&lt;unknown&gt;</code>.</li>\n</ul>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Unknown</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">parse</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">unknown</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">value</span> is <span data-k=\"name\">string</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">        <span data-k=\"keyword\">return</span> <span data-k=\"name\">value</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// narrowed by the guard</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"function\">todo</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;...&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Event</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"property\">payload</span><span data-k=\"punct\">:</span> <span data-k=\"type\">unknown</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// induces existential T via Event&lt;T&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">ErasedEvent</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\">    <span data-k=\"property\">payload</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Dynamic</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">unknown</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// one fixed erased representation</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>For genuinely heterogeneous storage, <code>Dynamic&lt;unknown&gt;</code> serves as the explicit erased universal value: a fat pointer carrying the value and its runtime descriptor, introspectable via <a href=\"#reflection\">reflection</a> and narrowable (for runtime-discernible forms) via <code>is</code>.</p>\n<h2 id=\"string\">String</h2><p>Destack wants to be &quot;TypeScript++&quot;, and thus we also follow JavaScript&#39;s string behavior: <code>string</code> length and positional access are <em>defined</em> in terms of UTF-16 code units, and - just like TS&#39;s own string iterator - iteration yields Unicode code points (mapping to <code>char</code>).</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">String</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">text</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;héllo&quot;;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"name\">text</span><span data-k=\"punct\">.</span><span data-k=\"property\">length</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">usize</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// UTF-16 code units, as in JS</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">c</span> <span data-k=\"keyword\">of</span> <span data-k=\"name\">text</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"name\">c</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">char</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// iteration by code point, as in JS</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Destack is stricter than TS for <code>string</code> indexing: <code>text[i]</code> gives a <code>char</code>, and indexing into a lone surrogate <a href=\"/docs/language/expressions/#panics\">traps</a> (a lone surrogate is virtually always a bug, and the views below are the explicit alternatives).\nFor the three main ways of looking at a string, the standard library provides explicit projections:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>View</th>\n<th>Type</th>\n<th>Meaning</th>\n</tr>\n</thead><tbody><tr>\n<td><code>text.units()</code></td>\n<td><code>[uint16]</code>-shaped view</td>\n<td>raw UTF-16 code units (JS&#39;s indexing model)</td>\n</tr>\n<tr>\n<td><code>text.chars()</code></td>\n<td>iterator of <code>char</code></td>\n<td>Unicode scalar values</td>\n</tr>\n<tr>\n<td><code>text.bytes()</code></td>\n<td><code>[uint8]</code>-shaped view</td>\n<td>UTF-8 bytes</td>\n</tr>\n</tbody></table></div><p>On native targets, <code>string</code> is immutable owned UTF-8 (the library&#39;s <code>String</code> literally holds <code>bytes: Unique&lt;[uint8]&gt;</code>); on JS/TS targets, strings are the host engine&#39;s strings.</p>\n<h2 id=\"intervals\">Intervals</h2><p>Ranges in type position become an interval type over <em>bounded</em> sets like <code>int</code>, <code>bigint</code>, or <code>char</code>; basically, an interval type is a static subset of its scalar type (e.g., <code>1..4</code> in type position is equivalent to <code>1 | 2 | 3</code>).\nAssignments to interval-typed places must already have an interval-compatible type - the compiler does <em>not</em> prove arithmetic expressions stay inside intervals and we do not insert implicit runtime checks for interval assignments.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Intervals</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">Digit</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">9</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">LowerAscii</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">'a'</span><span data-k=\"punct\">..=</span><span data-k=\"string\">'z'</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">UserPort</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">1024</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">65535</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">digit</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Digit</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">7</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">letter</span><span data-k=\"punct\">:</span> <span data-k=\"type\">LowerAscii</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">'m'</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">port</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserPort</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">8080</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"name\">digit</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">int</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"name\">letter</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">char</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"name\">port</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">int</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Interval types also compose with unions, aliases, and newtypes:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Intervals</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">HexDigit</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">9</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">&quot;a&quot;</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">&quot;b&quot;</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">&quot;c&quot;</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">&quot;d&quot;</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">&quot;e&quot;</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">&quot;f&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">NonZeroByte</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">255</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Port</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">65535</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Intervals can also constrain static parameters:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Intervals</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">InlineBuffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"type\">N</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">4096</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">storage</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">T</span><span data-k=\"punct\">;</span> <span data-k=\"type\">N</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Because interval types are basically just aliases to union types, they must be <em>bounded</em> sets, and as floating point are not bounded, plain <code>number</code>s cannot participate.\nIt follows that runtime values can become an interval type through ordinary <em>narrowing</em> - good old <a href=\"/docs/language/expressions/#patterns\">range patterns</a> and <a href=\"/docs/language/expressions/#guards\"><code>is</code> checks</a>:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Intervals</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Port</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">65535</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">parsePort</span><span data-k=\"punct\">(</span><span data-k=\"name\">n</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Port</span><span data-k=\"punct\">,</span> <span data-k=\"type\">ParseError</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">match</span> <span data-k=\"punct\">(</span><span data-k=\"name\">n</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">        <span data-k=\"literal\">1</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">65535</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">.</span><span data-k=\"property\">ok</span><span data-k=\"punct\">(</span><span data-k=\"type\">Port</span><span data-k=\"punct\">(</span><span data-k=\"name\">n</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span> <span data-k=\"comment\">// `n` is narrowed into the interval</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">        <span data-k=\"name\">_</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">.</span><span data-k=\"property\">err</span><span data-k=\"punct\">(</span><span data-k=\"type\">ParseError</span><span data-k=\"punct\">(</span><span data-k=\"string\">`port out of range: ${n}`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h2 id=\"newtypes\">Newtypes</h2><p>TypeScript is (primarily) structurally typed: an interface is satisfied by any value matching its shape, regardless of whether it explicitly <code>implement</code>s the interface.\nHowever, sometimes explicit nominality is helpful for correctness and expressiveness, and Destack adds <code>newtype</code> as the nominal counterpart to <code>type</code>.\nLike <code>type</code>, <code>newtype</code> follows its backing type: representable backings result in nominal concrete types, and constraint backings produce nominal constraints.</p>\n<p>For example, with plain <code>type</code>s and aliases, there is no actual protection against accidental assignment.\n(The TS ecosystem commonly resorts to &quot;branding&quot; hacks to work around this limitation.)</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Newtypes</span><span class=\"markdown-code__format\">.ts</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">type</span> <span class=\"hljs-title class_\">UserId</span> = <span class=\"hljs-built_in\">number</span>;</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span class=\"hljs-number\">0</span> <span class=\"hljs-keyword\">satisfies</span> <span class=\"hljs-built_in\">number</span>; <span class=\"hljs-comment\">// OK, TS is happy, but ouch</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span class=\"hljs-keyword\">type</span> <span class=\"hljs-title class_\">OrderTag</span> = <span class=\"hljs-built_in\">string</span>;</span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span class=\"hljs-string\">&quot;invalid&quot;</span> <span class=\"hljs-keyword\">satisfies</span> <span class=\"hljs-title class_\">OrderTag</span>; <span class=\"hljs-comment\">// OK, TS still happy, also ouch</span></span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Newtypes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">UserId</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">userId</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserId</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: number is not UserId</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">OrderTag</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">orderTag</span><span data-k=\"punct\">:</span> <span data-k=\"type\">OrderTag</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;invalid&quot;</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: string is not OrderTag</span></span></span></code></pre></figure><p>To construct a concrete newtype value, use explicit <code>T(..)</code> call syntax:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Newtypes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">UserId</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"type\">UserId</span><span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">)</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">OrderTag</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"type\">OrderTag</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;tag&quot;</span><span data-k=\"punct\">)</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">OrderTag</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"type\">number</span><span data-k=\"punct\">,</span> <span data-k=\"type\">number</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"type\">Point</span><span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">)</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Rectangle</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">    <span data-k=\"property\">start</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\">    <span data-k=\"property\">end</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"type\">Rectangle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">start</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">(</span><span data-k=\"literal\">0</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">)</span><span data-k=\"punct\">,</span> <span data-k=\"property\">end</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Rectangle</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">AuthenticatedUser</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\"><span data-k=\"type\">AuthenticatedUser</span><span data-k=\"punct\">(</span><span data-k=\"name\">user</span><span data-k=\"punct\">)</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">AuthenticatedUser</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Concrete newtypes are representation-transparent to the compiler but opaque to the type system.\nConstruction and projection across the backing boundary are explicit at the type level and of course &quot;zero-cost&quot; at runtime:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Newtypes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">id</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">raw</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">id</span> <span data-k=\"keyword\">as</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h2 id=\"newtype-interfaces\">Newtype Interfaces</h2><p>Newtype declarations add nominality to their backing type, and Destack also supports <strong>nominal interfaces</strong> using the <code>newtype</code> modifier on <code>interface</code> declarations.\n(This makes newtype interfaces behave essentially like traits in other languages, no weird &quot;branding tricks&quot; required.)</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Newtype Interfaces</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// structural interface (standard TypeScript behavior)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">interface</span> <span data-k=\"type\">Drawable</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">draw</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Drawable</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">draw</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// OK: structural match</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// nominal interface (requires explicit `implements`)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"keyword\">interface</span> <span data-k=\"type\">Add</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span> <span data-k=\"punct\">=</span> this<span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Output</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">    <span data-k=\"property\">add</span><span data-k=\"punct\">(</span><span data-k=\"name\">other</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> this<span data-k=\"punct\">.</span><span data-k=\"type\">Output</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Nominal interfaces require <strong>explicit <code>implements</code></strong> clauses, so structural compatibility alone doesn&#39;t satisfy the constraint (unlike with regular <code>interface</code>).\nNewtype interfaces are used for explicit behavioral traits like <a href=\"/docs/language/expressions/#operators\">operator interfaces</a> (e.g., <code>Add</code>, <code>Compare</code>), and for <a href=\"/docs/language/memory/#capabilities\">capability traits</a> (e.g., <code>Send</code>, <code>Sync</code>, <code>Copy</code>, and <code>Clone</code>).\nA <code>newtype interface</code> is nominal as a constraint, but it is still not a concrete value representation.</p>\n<h2 id=\"extensions\">Extensions</h2><p>It is sometimes convenient to attach additional logic and data directly to a type, even and especially when the type is not defined locally (in the same module or even the same package).\nRust supports this with <code>impl</code> blocks (and only <code>impl</code> blocks, actually), and Destack supports <em>additional</em> <code>extension</code>s to add instance and static members to any <em>nominal</em> type:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Extensions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Vector2</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"property\">constructor</span><span data-k=\"punct\">(</span><span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">        <span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">x</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">x</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">        <span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">y</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">y</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// extension may be in a different file or package altogether</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">extension</span> <span data-k=\"keyword\">of</span> <span data-k=\"type\">Vector2</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">static</span> <span data-k=\"property\">ZERO</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Vector2</span><span data-k=\"punct\">(</span><span data-k=\"literal\">0.0</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0.0</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\">    <span data-k=\"property\">magnitude</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\">        <span data-k=\"keyword\">return</span> <span data-k=\"punct\">(</span><span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">x</span> <span data-k=\"punct\">*</span> <span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">x</span> <span data-k=\"punct\">+</span> <span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">y</span> <span data-k=\"punct\">*</span> <span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">y</span><span data-k=\"punct\">)</span><span data-k=\"punct\">.</span><span data-k=\"property\">sqrt</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">18</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Extensions can be added to any <strong>nominal type</strong>, including <code>struct</code>, <code>class</code>, <code>enum</code>, and <code>newtype</code>, whether defined locally or in a foreign / imported module.\nPlain type aliases (<code>type X = ...</code>) and structural types (<code>{ x: number }</code>) cannot receive extensions because it would be unclear when they should apply.</p>\n<p>Extensions can also be named for and then referenced explicitly for export and import:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Extensions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;@/model/user&quot;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">export</span> <span data-k=\"keyword\">extension</span> <span data-k=\"type\">UserUtils</span> <span data-k=\"keyword\">of</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"property\">validate</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">boolean</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">        <span data-k=\"function\">todo</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;...&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>The visibility of extension members follows from their placement:</p>\n<ul>\n<li><strong>Same file as type</strong>: Extensions are automatically visible wherever the type is used.</li>\n<li><strong>Anonymous on foreign type</strong>: Only visible in the file where declared (<code>extension of int32 { ... }</code>).</li>\n<li><strong>Named on foreign type</strong>: Must be explicitly imported to use (<code>export extension DateUtils of Date { ... }</code>).</li>\n</ul>\n<h3 id=\"blankets\">Blankets</h3><p>Extensions may declare their own generic parameters to extend generic types, and a generic extension over a whole family of instantiations is a &quot;blanket&quot; extension (once again, similar to Rust):</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Blankets</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">extension</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">of</span> <span data-k=\"type\">Box</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">isEmpty</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">boolean</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">        <span data-k=\"comment\">// ...</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// conditional conformance: Box&lt;T&gt; is Show only when T is too</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">extension</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">of</span> <span data-k=\"type\">Box</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">implements</span> <span data-k=\"type\">Show</span> <span data-k=\"keyword\">where</span> <span data-k=\"type\">T</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Show</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"property\">show</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">        <span data-k=\"string\">`Box(${this.value.show()})`</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>The target of a blanket decides the scope of the claims it may make:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Blanket</th>\n<th>Example</th>\n<th>Who may declare it</th>\n</tr>\n</thead><tbody><tr>\n<td>Members over a bounded parameter</td>\n<td><code>extension Arithmetic&lt;T: int&gt; of T { ... }</code></td>\n<td>anyone</td>\n</tr>\n<tr>\n<td><code>implements</code> over a nominal application</td>\n<td><code>extension&lt;T&gt; of Box&lt;T&gt; implements Show</code></td>\n<td>anyone</td>\n</tr>\n<tr>\n<td><code>implements</code> over a bare bounded parameter</td>\n<td><code>extension&lt;T: Equal&gt; of T implements PartialEqual</code></td>\n<td>only the package declaring the interface</td>\n</tr>\n</tbody></table></div><p>Member blankets are lexical like all extension members, so the bound just names the candidate domain and nothing can surprise code that didn&#39;t import it.\n(Unbounded targets - including the <code>T: unknown</code> spelling of the same thing - are rejected, because methods on <em>everything</em> pollute every candidate set.)</p>\n<p>An <code>implements</code> blanket makes a global claim, so it needs a clear owner: a nominal target gives the conflict surface one, while an open-domain claim over every type that ever satisfies a bound belongs to the contract&#39;s owner.\nThat last form is also how interface hierarchies ship their bridges anyway:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Blankets</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// in the package declaring PartialEqual</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">extension</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Equal</span><span data-k=\"punct\">&gt;</span> <span data-k=\"keyword\">of</span> <span data-k=\"type\">T</span> <span data-k=\"keyword\">implements</span> <span data-k=\"type\">PartialEqual</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"comment\">// ...</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>All <code>implements</code> blankets participate in the same general coherence rules: overlapping implementations of the same interface for the same type - including blanket-vs-specific overlap - are a program-wide error (see <a href=\"/docs/language/expressions/#coherence\">Coherence</a>).</p>\n<h2 id=\"enums\">Enums</h2><p>Enums are nominal aliases to a set of constants, just like in TypeScript, but in Destack, enums do <em>not</em> implicitly cast to their backing type and explicit conversions are required for the backing value type.\nLike other nominal types, enums can carry instance and static members, and of course can also receive extensions.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Enums</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">enum</span> <span data-k=\"type\">Priority</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">Low</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">Medium</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"property\">High</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">,</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">static</span> <span data-k=\"property\">Default</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Priority</span><span data-k=\"punct\">.</span><span data-k=\"property\">Medium</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"property\">label</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">        <span data-k=\"keyword\">match</span> <span data-k=\"punct\">(</span><span data-k=\"name\">this</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">            <span data-k=\"type\">Low</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;low&quot;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">            <span data-k=\"type\">Medium</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;medium&quot;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\">            <span data-k=\"type\">High</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;high&quot;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\">        <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h2 id=\"tagged-unions\">Tagged Unions</h2><p>Discriminated unions are very convenient and fit well into existing TypeScript, but by themselves lack nominal containers (and items) to attach behavior to.\nUsing Destack&#39;s nominality via <code>newtype</code> and the builtin <code>Tagged</code> <a href=\"/docs/language/expressions/#derive\"><code>derive</code></a>, TypeScript&#39;s well known discriminated unions become even more ergonomic sum types:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Tagged Unions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">@<span data-k=\"function\">derive</span><span data-k=\"punct\">(</span><span data-k=\"type\">Tagged</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Shape</span> <span data-k=\"punct\">=</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">|</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">kind</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;rectangle&quot;</span><span data-k=\"punct\">;</span> <span data-k=\"property\">width</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span> <span data-k=\"property\">height</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">|</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">kind</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;circle&quot;</span><span data-k=\"punct\">;</span> <span data-k=\"property\">radius</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">extension</span> <span data-k=\"keyword\">of</span> <span data-k=\"type\">Shape</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">static</span> <span data-k=\"property\">DEFAULT</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"property\">Rectangle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">width</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">10</span><span data-k=\"punct\">,</span> <span data-k=\"property\">height</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">20</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"property\">variant</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">        <span data-k=\"keyword\">match</span> <span data-k=\"punct\">(</span><span data-k=\"name\">this</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">            <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"property\">Rectangle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">width</span><span data-k=\"punct\">,</span> <span data-k=\"property\">height</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;rectangle&quot;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\">            <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"property\">Circle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">radius</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;circle&quot;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\">        <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// create values of tagged newtype unions with &lt;Type&gt;.&lt;Variant&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">18</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">rectangle</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"property\">Rectangle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">width</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">10</span><span data-k=\"punct\">,</span> <span data-k=\"property\">height</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">20</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">19</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">circle</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"property\">Circle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">radius</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">5</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>The discriminant field is inferred from the union via the <code>Tagged</code> derive macro from the unique common field whose variants carry distinct literal values.\nIt behaves essentially just like builtin sugar that is expanded into a constructor function:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Tagged Unions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">extension</span> <span data-k=\"keyword\">of</span> <span data-k=\"type\">Shape</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"comment\">// for each tagged variant, expose a &quot;constructor&quot; by tag</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">static</span> <span data-k=\"property\">Rectangle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">width</span><span data-k=\"punct\">:</span> <span data-k=\"name\">int32</span><span data-k=\"punct\">,</span> <span data-k=\"property\">height</span><span data-k=\"punct\">:</span> <span data-k=\"name\">int32</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">        <span data-k=\"punct\">{</span> <span data-k=\"property\">kind</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;rectangle&quot;</span><span data-k=\"punct\">,</span> width<span data-k=\"punct\">,</span> height <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"comment\">// ...</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Except that <code>Tagged</code> enums also work in pattern position, and - thanks to some compiler magic that wouldn&#39;t work in pure userland - the variant head behaves like a real variant pattern:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Tagged Unions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">match</span> <span data-k=\"punct\">(</span><span data-k=\"name\">shape</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"property\">Rectangle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">width</span><span data-k=\"punct\">,</span> <span data-k=\"property\">height</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">width</span> <span data-k=\"punct\">*</span> <span data-k=\"name\">height</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"property\">Circle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">radius</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">radius</span> <span data-k=\"punct\">*</span> <span data-k=\"name\">radius</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>By default, string discriminants are exposed as <code>UpperCamelCase</code> constructor names - the other supported naming policies are:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Tagged Casing</th>\n<th>Example</th>\n</tr>\n</thead><tbody><tr>\n<td><code>&quot;preserve&quot;</code></td>\n<td><code>rectangle</code> → <code>rectangle</code></td>\n</tr>\n<tr>\n<td><code>&quot;camelCase&quot;</code></td>\n<td><code>rectangle_shape</code> → <code>rectangleShape</code></td>\n</tr>\n<tr>\n<td><code>&quot;UpperCamelCase&quot;</code></td>\n<td><code>rectangle_shape</code> → <code>RectangleShape</code></td>\n</tr>\n<tr>\n<td><code>&quot;snake_case&quot;</code></td>\n<td><code>RectangleShape</code> → <code>rectangle_shape</code></td>\n</tr>\n<tr>\n<td><code>&quot;SCREAMING_SNAKE_CASE&quot;</code></td>\n<td><code>RectangleShape</code> → <code>RECTANGLE_SHAPE</code></td>\n</tr>\n</tbody></table></div><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Tagged Unions</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">@<span data-k=\"function\">derive</span><span data-k=\"punct\">(</span><span data-k=\"type\">Tagged</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">case</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;preserve&quot;</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"type\">Shape</span> <span data-k=\"punct\">=</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">|</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">kind</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;rectangle&quot;</span><span data-k=\"punct\">;</span> <span data-k=\"property\">width</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span> <span data-k=\"property\">height</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">|</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">kind</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;circle&quot;</span><span data-k=\"punct\">;</span> <span data-k=\"property\">radius</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">rectangle</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"property\">rectangle</span><span data-k=\"punct\">(</span> <span data-k=\"comment\">/* ... */</span> <span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">circle</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"property\">circle</span><span data-k=\"punct\">(</span> <span data-k=\"comment\">/* ... */</span> <span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h2 id=\"structs\">Structs</h2><p>Structs are nominal value types for data with a fixed shape, but without reference identity, constructors, or inheritance.\nBasically, structs are just their values with a name attached, much like structs in other &quot;systems-y&quot; managed languages.\nStructs are created via the usual <code>T { .. }</code> constructor form to distinguish them from regular objects, they do not and cannot have <code>new</code>-like <code>constructor</code>s of their own.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Structs</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> x<span data-k=\"punct\">,</span> y <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// OK</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span> x<span data-k=\"punct\">,</span> y <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>        <span data-k=\"comment\">// ERROR: plain object is not Point</span></span></span></code></pre></figure><p>Like all type positions, struct expressions also support the <code>_</code> placeholder for contextual type inference:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Structs</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">let</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">_</span> <span data-k=\"punct\">{</span> x<span data-k=\"punct\">,</span> y <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// OK</span></code></pre></figure><p>Struct expressions can update an existing struct value with the familiar &quot;spread&quot; operator <code>...expr</code>, keeping the nominal struct type:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Structs</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">moved</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">x</span><span data-k=\"punct\">,</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">10.0</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"name\">moved</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Plain object spreads can also read the fields of a struct value, but they produce a structural object rather than the nominal struct.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Structs</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">object</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">x</span><span data-k=\"punct\">,</span> <span data-k=\"property\">label</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;origin&quot;</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// x: Point</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"name\">object</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span> <span data-k=\"property\">label</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Conversely, struct expressions can also spread <em>from</em> object literal expressions (when the field set satisfies the struct):</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Structs</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">base</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1.0</span><span data-k=\"punct\">,</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">2.0</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">_</span> <span data-k=\"punct\">{</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">base</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Classes can also be spread into plain object expressions, following TypeScript&#39;s object-shaped model, but the result is structural and carries only fields.</p>\n<h2 id=\"classes\">Classes</h2><p>Classes follow the TypeScript-shaped model for managed objects with identity - except, of course, without the prototype chain or any dynamic or unsound shenanigans.\nAlso, class fields require every instance field to be initialized by its declaration or every constructor path.\n(Optional fields do not need eager initialization, they default to <code>undefined</code>.)</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Classes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Counter</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"property\">constructor</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">        <span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">value</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">value</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"property\">increment</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">        <span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">value</span> <span data-k=\"punct\">+=</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">        <span data-k=\"name\">this</span><span data-k=\"punct\">.</span><span data-k=\"property\">value</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">counter</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Counter</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Counter</span><span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"><span data-k=\"name\">counter</span><span data-k=\"punct\">.</span><span data-k=\"property\">increment</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Like structs, classes support the <code>_</code> placeholder for type inference:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Classes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">counter</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Counter</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"name\">_</span><span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"name\">counter</span><span data-k=\"punct\">.</span><span data-k=\"property\">increment</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Class methods are concrete (have only one implementation) by default and must be declared as <code>virtual</code> to enable <em>virtual</em> dispatch of instances methods in subclasses.\nSimilarly, class methods are marked as <code>abstract</code> to <em>require</em> an <code>override</code> in an implementing subclass such that the class can actually be constructed.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Classes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">abstract</span> <span data-k=\"keyword\">class</span> <span data-k=\"type\">Logger</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">abstract</span> <span data-k=\"property\">write</span><span data-k=\"punct\">(</span><span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    virtual <span data-k=\"property\">flush</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Additionally, classes may be marked <code>final</code> to prevent downstream classes from extending the declaration.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Classes</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">final <span data-k=\"keyword\">class</span> <span data-k=\"type\">PacketHeader</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">length</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint32</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>TypeScript visibility modifiers are fully supported, but the <code>#field</code> private syntax form is redundant and not allowed in <code>.ds</code> files (use <code>private</code> instead).</p>\n<h2 id=\"arrays-slices-and-tuples\">Arrays, Slices and Tuples</h2><p>Destack supports richer sequence forms beyond TypeScript&#39;s dynamic arrays - <code>T[]</code> / <code>Array&lt;T&gt;</code> with explicit slices, fixed arrays, and tuples.\nUnfortunately, not much syntax was left here, so we had to adopt the slightly non-TS-y syntax forms of <code>[T]</code> and <code>[T; N]</code> for slices and fixed arrays, respectively.</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Forms</th>\n<th>Representation</th>\n<th>Meaning</th>\n</tr>\n</thead><tbody><tr>\n<td><code>T[]</code>, <code>Array&lt;T&gt;</code></td>\n<td>Collection class</td>\n<td>Growable, homogeneous, dense sequence with capacity</td>\n</tr>\n<tr>\n<td><code>[T]</code>, <code>Slice&lt;T&gt;</code></td>\n<td>Slice header</td>\n<td>Pointer plus length, no capacity</td>\n</tr>\n<tr>\n<td><code>[T; N]</code>, <code>FixedArray&lt;T, N&gt;</code></td>\n<td>Inline array</td>\n<td>Exactly <code>N</code> elements stored in the value</td>\n</tr>\n<tr>\n<td><code>(A, B)</code></td>\n<td>Inline product</td>\n<td>Heterogeneous sequence of owned values</td>\n</tr>\n</tbody></table></div><p>Dynamic arrays are just class, regular managed objects with identity, while slices, fixed arrays, and tuples are value types (<code>struct</code>s, basically).\nHowever, Destack does not permit holes in arrays or any other sequences, and indexing into <code>T[]</code> therefore always returns <code>T</code>.\nUnlike in Rust, and somewhat more like in Go, Destack&#39;s <code>[T]</code> slice is a sized fat pointer and thus a first-class slice <em>value</em>.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Arrays, Slices and Tuples</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>       <span data-k=\"comment\">// dynamic array of int32</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Array</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">int32</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">x</span><span data-k=\"punct\">;</span>          <span data-k=\"comment\">// dynamic array of int32</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">int32</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>       <span data-k=\"comment\">// slice of int32</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Slice</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">int32</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">x</span><span data-k=\"punct\">;</span>          <span data-k=\"comment\">// slice of int32</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">int32</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>    <span data-k=\"comment\">// fixed array of int32</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">FixedArray</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">int32</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">x</span><span data-k=\"punct\">;</span>  <span data-k=\"comment\">// fixed array of int32</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">(</span><span data-k=\"type\">int32</span><span data-k=\"punct\">,</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">,</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// tuple of int32</span></span></span></code></pre></figure><p>By default, array literals are dynamic arrays but can coerce to other sequence forms in place when contextually required.\nFixed arrays are just a homogeneous sequence of values whose length is statically known (and part of the type): they are inline value/layout types by default, and definitionally cannot grow.\n(If you need an array that can grow, use a dynamic array, i.e. <code>T[]</code> / <code>Array&lt;T&gt;</code>)</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Arrays, Slices and Tuples</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">Block</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">4096</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// 4KB of uint8</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">Vec3</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"type\">float32</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>   <span data-k=\"comment\">// 3 float32s</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">rgb</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"literal\">255</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">128</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">zeroes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">32</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"literal\">0</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">32</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Fixed arrays and slices also work directly in patterns: fixed array patterns already know their length statically, while slice patterns can use a rest binding for the tail / head:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Arrays, Slices and Tuples</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">rgb</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"punct\">[</span><span data-k=\"name\">r</span><span data-k=\"punct\">,</span> <span data-k=\"name\">g</span><span data-k=\"punct\">,</span> <span data-k=\"name\">b</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">rgb</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">match</span> <span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">[</span><span data-k=\"literal\">0x89</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0x50</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0x4e</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0x47</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">rest</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"function\">parsePng</span><span data-k=\"punct\">(</span><span data-k=\"name\">rest</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">[</span><span data-k=\"literal\">0xff</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0xd8</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">rest</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"function\">parseJpeg</span><span data-k=\"punct\">(</span><span data-k=\"name\">rest</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"name\">_</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">.</span><span data-k=\"property\">err</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;unknown image format&quot;</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Tuples are fixed heterogeneous products, and of course also work as patterns:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Arrays, Slices and Tuples</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">(</span><span data-k=\"type\">int32</span><span data-k=\"punct\">,</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"punct\">(</span><span data-k=\"name\">x</span><span data-k=\"punct\">,</span> <span data-k=\"name\">_</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=</span> <span data-k=\"function\">getPoint</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>One-element tuples use a trailing comma, empty tuples are just <code>()</code>.\nSince tuples are also just value containers, empty tuples occupy no space.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Arrays, Slices and Tuples</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">One</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"type\">int32</span><span data-k=\"punct\">,</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">one</span><span data-k=\"punct\">:</span> <span data-k=\"type\">One</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">,</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">empty</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><h2 id=\"readonly\">Readonly</h2><p>TypeScript&#39;s <code>readonly</code> is shallow, while in <code>.ds</code>, <code>readonly T</code> is always a <em>deep</em> read-only view of <code>T</code>.\nThat is, <code>readonly T</code> forbids <em>any</em> mutation through its <code>T</code>, and <code>readonly T</code> cannot be assigned to <code>T</code>, including via nested members.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Readonly</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Profile</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"property\">profile</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Profile</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"property\">tags</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">profile</span><span data-k=\"punct\">.</span><span data-k=\"property\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;Grace&quot;</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// ERROR: readonly view</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"property\">tags</span><span data-k=\"punct\">[</span><span data-k=\"literal\">0</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;admin&quot;</span><span data-k=\"punct\">;</span>      <span data-k=\"comment\">// ERROR: readonly view</span></span></span></code></pre></figure><h2 id=\"generics\">Generics</h2><p>Destack supports classic TypeScript-shaped generics: inference, constraints, defaults, conditional types, mapped types, indexed access types, and the rest of the usual machinery.\nUnlike in TypeScript, however, Destack&#39;s parameters can also represent <em>values</em> that are then substituted into expressions <em>and</em> both values and types are available during inference.</p>\n<p>To distinguish static value parameters from static type parameters (and literal value types), we use the <code>comptime</code> modifier on the generic parameter declaration (akin to Rust&#39;s <code>const</code> modifier, alas this was already taken in TypeScript):</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Generics</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">type</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">N</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"type\">N</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></code></pre></figure><p>Generic bounds can use the cleaner <code>&lt;T: Constraint&gt;</code> form, just like dynamic parameters.\nUnlike with <code>comptime &lt;expr&gt;</code> (discussed later), the <code>comptime</code> modifier merely means that <code>N</code> is a generic value parameter that has to be evaluatable as a static term during inference.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Generics</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">copy</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"type\">N</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">src</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">T</span><span data-k=\"punct\">;</span> <span data-k=\"type\">N</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">T</span><span data-k=\"punct\">;</span> <span data-k=\"type\">N</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">let</span> <span data-k=\"name\">dst</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">T</span><span data-k=\"punct\">;</span> <span data-k=\"type\">N</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">let</span> <span data-k=\"name\">i</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span> <span data-k=\"name\">i</span> <span data-k=\"punct\">&lt;</span> <span data-k=\"type\">N</span><span data-k=\"punct\">;</span> <span data-k=\"name\">i</span><span data-k=\"punct\">++</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">        <span data-k=\"name\">dst</span><span data-k=\"punct\">[</span><span data-k=\"name\">i</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">src</span><span data-k=\"punct\">[</span><span data-k=\"name\">i</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"name\">dst</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>As in TypeScript, type parameters may include a <code>const</code> modifier to retain &quot;fresh&quot; precision in arguments.\nTo be clear, <code>const T</code> is about type widening, and <code>const T</code> parameters are still <em>type</em> parameters (unlike <code>comptime N</code>), and they&#39;re also the reason we had to use a different syntax for true value parameters in the first place.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Generics</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">freeze</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">const</span> <span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">value</span> <span data-k=\"punct\">=</span> <span data-k=\"function\">freeze</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">kind</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;ready&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"property\">level</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"name\">value</span><span data-k=\"punct\">.</span><span data-k=\"property\">kind</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;ready&quot;</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Dynamic parameters may <em>also</em> be marked <code>comptime</code> when the caller should pass an ordinary argument expression that is still required to be evaluatable as a static term during compile time, mostly as a readability affordance where spelling the value as a generic argument would be awkward or constraining.\n(It also means we can progressively make an argument statically known, without forcing a generic signature, which is nice and ergonomic in some situations.)</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Generics</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">repeat</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"name\">count</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">T</span><span data-k=\"punct\">;</span> <span data-k=\"name\">count</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"comment\">// ...</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">values</span> <span data-k=\"punct\">=</span> <span data-k=\"function\">repeat</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;x&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"name\">values</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">[</span><span data-k=\"type\">string</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Like dynamic parameters, Destack&#39;s generic parameters also support <code>...</code> forms:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Generics</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">type</span> <span data-k=\"type\">Callback</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"type\">Parameters</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Return</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">parameters</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Parameters</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"type\">Return</span><span data-k=\"punct\">;</span></code></pre></figure><p>Type inference (including generics) works across modules, even when modules circularly reference one another - though of course, this should be used with caution and can lead to longer compile times because it forces large connected components during inference checking.</p>\n<h2 id=\"variance\">Variance</h2><p>Variance describes how typing and subtyping relations work for generic types, including for all the types that managed language users may not even usually think of as generic (like <code>Array</code>).\nMutable covariance - the fact that we can assign <code>Circle[]</code> to <code>Shape[]</code> and then mutate <code>Circle[]</code> <em>through</em> the widened <code>Shape[]</code> alias - is one of TypeScript&#39;s best known soundness holes and a classic footgun.\nBecause Destack needs to be actually sound, we only support this sort of widening when it is unambiguously safe:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Position</th>\n<th>Variance</th>\n<th>Example</th>\n</tr>\n</thead><tbody><tr>\n<td>Readonly positions</td>\n<td>covariant</td>\n<td><code>readonly Circle[]</code> is assignable to <code>readonly Shape[]</code></td>\n</tr>\n<tr>\n<td>Mutable storage positions</td>\n<td>invariant</td>\n<td><code>Circle[]</code> is <em>not</em> assignable to <code>Shape[]</code></td>\n</tr>\n<tr>\n<td>Function parameters</td>\n<td>contravariant</td>\n<td><code>(shape: Shape) =&gt; void</code> is assignable to <code>(circle: Circle) =&gt; void</code></td>\n</tr>\n<tr>\n<td>Function returns</td>\n<td>covariant</td>\n<td><code>() =&gt; Circle</code> is assignable to <code>() =&gt; Shape</code></td>\n</tr>\n</tbody></table></div><p>For generic types, variance is derived per parameter from each generic parameter&#39;s usage in the declaration (like in TypeScript): a parameter that only comes &quot;<em>out</em>&quot; (returns, readable fields) is covariant, one that only goes &quot;<em>in</em>&quot; (parameters, writable fields) is contravariant, and one that does both - a mutable field counts as both at once - is invariant.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Variance</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Source</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">take</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span> <span data-k=\"punct\">}</span>                      <span data-k=\"comment\">// T only comes out -&gt; covariant</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Sink</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span>   <span data-k=\"punct\">{</span> <span data-k=\"property\">put</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">}</span>            <span data-k=\"comment\">// T only goes in   -&gt; contravariant</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">class</span> <span data-k=\"type\">Pipe</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span>   <span data-k=\"punct\">{</span> <span data-k=\"property\">take</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">;</span> <span data-k=\"property\">put</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">}</span> <span data-k=\"comment\">// both             -&gt; invariant</span></span></span></code></pre></figure><p>And because <code>Array&lt;T&gt;</code> is just a regular (well known) standard library type, and it has both readable and writable positions for its generic parameter, <code>Array&lt;T&gt;</code> is invariant in <code>T</code>:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Variance</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">circles</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Circle</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">shapes</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Shape</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">circles</span><span data-k=\"punct\">;</span>        <span data-k=\"comment\">// ERROR: mutable arrays are invariant</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">view</span><span data-k=\"punct\">:</span> <span data-k=\"keyword\">readonly</span> <span data-k=\"type\">Shape</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">circles</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// OK: readonly views are covariant</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">copies</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Shape</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">circles</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>   <span data-k=\"comment\">// OK: explicit copy reifies Shape elements</span></span></span></code></pre></figure><p>For the other spellings of &quot;a collection of shapes&quot;, the element representation decides everything:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Element type</th>\n<th><code>Shape[]</code> means</th>\n<th>Holds</th>\n</tr>\n</thead><tbody><tr>\n<td><code>class Shape</code></td>\n<td>array of managed references</td>\n<td>any subclass, open set</td>\n</tr>\n<tr>\n<td><code>type</code> / <code>newtype</code> union</td>\n<td>array of tagged variant layouts</td>\n<td>the listed variants, closed set</td>\n</tr>\n<tr>\n<td><code>interface Shape</code></td>\n<td>induced generic, <code>Array&lt;T: Shape&gt;</code></td>\n<td>one concrete <code>T</code>, homogeneous</td>\n</tr>\n<tr>\n<td><code>Dynamic&lt;Shape&gt;</code></td>\n<td>array of erased fat pointers</td>\n<td>any implementor, open set</td>\n</tr>\n</tbody></table></div><h2 id=\"static\">Static</h2><p>Unlike TypeScript, Destack actually <em>compiles</em>, so we need to figure out during &quot;compile time&quot; the final type of each value and fill in values for all the known constants.\nTo do this, we need to consider three different &quot;evaluation times&quot; between the source code and the actual executable:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>World</th>\n<th>Meaning</th>\n<th>Example</th>\n</tr>\n</thead><tbody><tr>\n<td>Static</td>\n<td>types, values, and relations known while checking</td>\n<td><code>T</code>, <code>N</code>, <code>this.Width</code>, <code>T extends string? A : B</code></td>\n</tr>\n<tr>\n<td>Comptime</td>\n<td>ordinary code explicitly evaluated by the compiler</td>\n<td><code>comptime factorial(10)</code></td>\n</tr>\n<tr>\n<td>Runtime</td>\n<td>ordinary program execution</td>\n<td><code>readFile(path)</code>, <code>worker.postMessage(msg)</code></td>\n</tr>\n</tbody></table></div><p>Type inference and static term evaluation are one and the same, which is why we get both fast generics and powerful type evaluation using <strong>static terms</strong>: a small subset of the language (like TypeScript type operators) available during type inference.\nAll dynamic <code>comptime &lt;expr&gt;</code> <em>execution</em> happens <em>after</em> type inference, so it can do anything that runtime code can do.\nThis keeps compilation fast and predictable, and thanks to TypeScript&#39;s flexible type algebra, static terms are still pretty powerful:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Input</th>\n<th>Example</th>\n</tr>\n</thead><tbody><tr>\n<td>Type parameters</td>\n<td><code>T</code></td>\n</tr>\n<tr>\n<td>Static value parameters</td>\n<td><code>N</code> in <code>function f&lt;comptime N: uint&gt;()</code></td>\n</tr>\n<tr>\n<td>Type aliases and generic applications</td>\n<td><code>Buffer&lt;N&gt;</code>, <code>Payload&lt;T&gt;</code></td>\n</tr>\n<tr>\n<td>Associated types and constants</td>\n<td><code>I.Item</code>, <code>Register.Width</code></td>\n</tr>\n<tr>\n<td>Static <code>const</code>s and imports</td>\n<td><code>N</code> imported from <code>./a.ds</code></td>\n</tr>\n<tr>\n<td>Enum members and nominal constants</td>\n<td><code>OperatingSystem.Windows</code></td>\n</tr>\n<tr>\n<td>Literal values</td>\n<td><code>4</code>, <code>&quot;shared&quot;</code>, <code>true</code></td>\n</tr>\n<tr>\n<td>Static operators</td>\n<td><code>N * 2</code>, <code>Mode == &quot;inline&quot;</code></td>\n</tr>\n<tr>\n<td>Contextual type form</td>\n<td><code>PlaceOf&lt;this&gt;</code> inside a type declaration</td>\n</tr>\n<tr>\n<td>Module and profile metadata</td>\n<td><code>import.meta.platform</code></td>\n</tr>\n<tr>\n<td>Type operators</td>\n<td><code>keyof T</code>, <code>T[K]</code>, <code>T extends string</code>, <code>T implements I</code></td>\n</tr>\n<tr>\n<td>Layout intrinsics</td>\n<td><code>sizeOf&lt;T&gt;()</code>, <code>alignOf&lt;T&gt;()</code></td>\n</tr>\n</tbody></table></div><p>Static terms are required wherever the language needs an inference-known answer: fixed array lengths, conditional types, associated members, static decorators, <a href=\"#layout\">layout queries</a>, and <a href=\"/docs/language/memory/#algebra\">placement algebra</a>.\nType inference may flow <em>out</em> of modules, but Destack does not support circular static inference or inference across modules in any way.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Static</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">Block</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">N</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"type\">N</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">Payload</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">T</span> <span data-k=\"keyword\">extends</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">?</span> <span data-k=\"type\">Utf8Payload</span> <span data-k=\"punct\">:</span> <span data-k=\"type\">BinaryPayload</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">BufferIndex</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Mode</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Mode</span> <span data-k=\"punct\">==</span> <span data-k=\"string\">&quot;inline&quot;</span> <span data-k=\"punct\">?</span> <span data-k=\"type\">InlineIndex</span> <span data-k=\"punct\">:</span> <span data-k=\"type\">ExternalIndex</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"type\">Mode</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;inline&quot;</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">&quot;external&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"property\">index</span><span data-k=\"punct\">:</span> <span data-k=\"type\">BufferIndex</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Mode</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"property\">data</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>In the <code>Buffer</code> example, <code>Mode</code> is carried as a generic value and used by a conditional type.\nThe declaration still has one checked field named <code>index</code>; only the field type changes by instantiation.\nGeneric-dependent static terms may select types, constants, layouts, and overloads, but they do not remove source nodes from a generic declaration.\nThat keeps generic declarations checked once, Rust-style, instead of turning generic instantiation into template expansion.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Static</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">size</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">Wide</span><span data-k=\"punct\">:</span> <span data-k=\"type\">boolean</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Wide</span> <span data-k=\"keyword\">extends</span> <span data-k=\"literal\">true</span> <span data-k=\"punct\">?</span> <span data-k=\"literal\">8</span> <span data-k=\"punct\">:</span> <span data-k=\"literal\">4</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">Wide</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">        <span data-k=\"keyword\">return</span> <span data-k=\"literal\">8</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">        <span data-k=\"keyword\">return</span> <span data-k=\"literal\">4</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><h2 id=\"associated-types-and-constants\">Associated Types and Constants</h2><p>Associated types and constants contribute static members to a type that can be reused within the type and its implementors but do not need to be exposed to every single caller.\nBoth associated types and constants also work in abstract types, and as they are associated with the type directly, they do not occupy any instance space on the type.\nAll statically known types and constants share the same static evaluation logic, and thus associated types and constants also mix with generic parameters, conditional types, decorators, and so on.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Associated Types and Constants</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"keyword\">interface</span> <span data-k=\"type\">Collection</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Item</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Return</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"property\">next</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">IteratorResult</span><span data-k=\"punct\">&lt;</span>this<span data-k=\"punct\">.</span><span data-k=\"type\">Item</span><span data-k=\"punct\">,</span> this<span data-k=\"punct\">.</span><span data-k=\"type\">Return</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">collect</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">I</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Collection</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">iter</span><span data-k=\"punct\">:</span> <span data-k=\"type\">I</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">I</span><span data-k=\"punct\">.</span><span data-k=\"type\">Item</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Associated types are type aliases scoped to some struct, class, or interface and can also reference the owner&#39;s generic parameters.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Associated Types and Constants</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">interface</span> <span data-k=\"type\">BufferPool</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Error</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"property\">acquire</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">count</span><span data-k=\"punct\">:</span> <span data-k=\"type\">usize</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span>this<span data-k=\"punct\">.</span><span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span> this<span data-k=\"punct\">.</span><span data-k=\"type\">Error</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"property\">release</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">buffer</span><span data-k=\"punct\">:</span> this<span data-k=\"punct\">.</span><span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Associated types can have their <em>own</em> generic parameters with the same generic parameter forms as ordinary declarations, including type parameters and <code>comptime</code> value parameters (these are generic associated types, often called GATs).</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Associated Types and Constants</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">interface</span> <span data-k=\"type\">Storage</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Handle</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Page</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">Size</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">SharedStorage</span> <span data-k=\"keyword\">implements</span> <span data-k=\"type\">Storage</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Handle</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> shared <span data-k=\"type\">StorageHandle</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Page</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">Size</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> shared <span data-k=\"type\">StoragePage</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Size</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>In addition to associated types, nominal type declarations also support associated constant members as static compile-time values.\nLike <code>static</code> members, <code>comptime const</code>s require no instance storage, but unlike <code>static</code> members, <code>comptime const</code>s are statically evaluated <em>during</em> compilation.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Associated Types and Constants</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">interface</span> <span data-k=\"type\">RegisterBlock</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">comptime</span> <span data-k=\"keyword\">const</span> <span data-k=\"type\">Width</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"property\">read</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> this<span data-k=\"punct\">.</span><span data-k=\"type\">Width</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\">    <span data-k=\"property\">write</span><span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> this<span data-k=\"punct\">.</span><span data-k=\"type\">Width</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Associated members participate in the same static evaluation / inference world, and so associated members can express dependent types and values that are dependent on others (including inferred!).</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Associated Types and Constants</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">interface</span> <span data-k=\"type\">Matrix</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Row</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">comptime</span> <span data-k=\"keyword\">const</span> <span data-k=\"type\">Width</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Row</span> <span data-k=\"keyword\">extends</span> <span data-k=\"name\">string</span> <span data-k=\"punct\">?</span> <span data-k=\"literal\">8</span> <span data-k=\"punct\">:</span> <span data-k=\"literal\">4</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Bytes</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> this<span data-k=\"punct\">.</span><span data-k=\"type\">Width</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Associated members (both types and constants) can be refined explicitly at application sites whenever an erased or constrained value needs a concrete associated surface with <code>type Name = T</code> for types and <code>comptime Name = value</code> for constants.</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Associated Types and Constants</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">readBlock</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">:</span> <span data-k=\"type\">RegisterBlock</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">Width</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">16</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">block</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">16</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></code></pre></figure><h2 id=\"constraints\">Constraints</h2><p>Sometimes, defining the constraints and relations for type parameters can become unwieldy or outright impossible with only type annotations on each individual term.\nDestack supports explicit (type-space) <code>where</code> clauses to define additional constraints for complex types and signatures, very much like Rust:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Constraints</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">merge</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int</span><span data-k=\"punct\">,</span> <span data-k=\"type\">U</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span> <span data-k=\"keyword\">where</span> <span data-k=\"type\">U</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Comparable</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"comment\">// ...</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>A <code>where</code> clause accepts the same constraint forms as inline bounds, plus a few relations that inline bounds cannot otherwise express:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Form</th>\n<th>Example</th>\n<th>Meaning</th>\n</tr>\n</thead><tbody><tr>\n<td>Interface bound</td>\n<td><code>T: Comparable&lt;U&gt;</code></td>\n<td>a parameter must satisfy a constraint</td>\n</tr>\n<tr>\n<td>Associated member bound</td>\n<td><code>I.Item: Display</code></td>\n<td>an associated type must satisfy a constraint</td>\n</tr>\n<tr>\n<td>Equality constraint</td>\n<td><code>T.Output == U</code></td>\n<td>two static terms must normalize to the same type or value</td>\n</tr>\n</tbody></table></div><h2 id=\"shapes\">Shapes</h2><p>Because Destack inherits TypeScript&#39;s type forms of <code>class</code>, <code>type</code> and <code>interface</code>, and then <em>adds</em> <code>struct</code> value types and nominality via <code>newtype</code>, we now have a spectrum of <em>six</em> different ways of spelling that something looks like a <code>Point { x: number; y: number }</code>.\nBleh.\nIt is what it is.\nA little unfortunate, but we couldn&#39;t figure out a good way to compress these shapes without losing either key additions like nominality and value types or compatibility guarantees like <code>type</code>, <code>interface</code>, and <code>class</code>.\nSo, here goes:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Form</th>\n<th>Role</th>\n<th>Representation</th>\n</tr>\n</thead><tbody><tr>\n<td><code>type Point = { x: number; y: number }</code></td>\n<td>Transparent alias for a type expression.</td>\n<td>Transparent</td>\n</tr>\n<tr>\n<td><code>interface Point { x: number; y: number }</code></td>\n<td>Named structural constraint with extension syntax.</td>\n<td>Transparent</td>\n</tr>\n<tr>\n<td><code>newtype interface Point { x: number; y: number }</code></td>\n<td>Nominal interface (trait).</td>\n<td>Transparent</td>\n</tr>\n<tr>\n<td><code>newtype Point = { x: number; y: number }</code></td>\n<td>Nominal wrapper over an (object) shape.</td>\n<td>Managed object</td>\n</tr>\n<tr>\n<td><code>struct Point { x: number; y: number }</code></td>\n<td>Nominal value product.</td>\n<td>Owned value</td>\n</tr>\n<tr>\n<td><code>class Point { x: number; y: number }</code></td>\n<td>Nominal identity object.</td>\n<td>Managed object</td>\n</tr>\n</tbody></table></div><p>Hopefully, these mostly behave as expected, even if the assortment is bigger than what one would usually get.\nThey do all actually fill slightly different niches, and, fortunately, they compose quite well, and let us think in terms of types, transparency, nominality, and layout as needed, which is quite neat.</p>\n<h2 id=\"representation\">Representation</h2><p>Destack&#39;s general philosophy is to let users opt <em>in</em> to additional control and complexity as needed - as much as possible, things should &quot;just work&quot; like in TypeScript.\nThat said, the actual memory representation of types does matter, and our unique blend of TypeScript type algebra and actual systems-y AOT compilation means that Destack needs to make representation tradeoffs differently from other languages.\nSpecifically, we distinguish three main axes of type behavior that affect representation:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Axis</th>\n<th>Question</th>\n<th>Examples</th>\n</tr>\n</thead><tbody><tr>\n<td><em>nominal</em> vs <em>structural</em></td>\n<td>must the type be constructed or implemented explicitly?</td>\n<td><code>newtype</code> / <code>struct</code> / <code>class</code> / <code>newtype interface</code> vs <code>type</code> / <code>{ x: number }</code></td>\n</tr>\n<tr>\n<td><em>transparent</em> vs <em>opaque</em></td>\n<td>does the name just expand to a type expression?</td>\n<td><code>type</code> vs <code>interface</code> / <code>struct</code> / <code>class</code> / <code>newtype</code></td>\n</tr>\n<tr>\n<td><em>concrete</em> vs <em>abstract</em></td>\n<td>is there already a representation we can store directly (the builtin <code>Concrete</code> bound)?</td>\n<td>primitives / <code>struct</code> / <code>class</code> vs bare constraints</td>\n</tr>\n</tbody></table></div><p>The position decides who commits to a representation: a <em>constraint</em> position leaves the choice to each use site, while a <em>storage</em> position makes the declaration commit.\nAll storage positions induce an implicit <code>Concrete</code> requirement on the value being stored, and <code>Concrete</code> is also available explicitly for the few cases where that&#39;s helpful (e.g. <code>type InlineBytes&lt;T: Concrete&gt; = [uint8; sizeOf&lt;T&gt;()]</code>).\nWherever a type can have multiple possible runtime representations, Destack induces an <em>implicit</em> generic parameter and monomorphizes all applications of that parameter, just like with an explicit generic type:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Representation</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">draw</span><span data-k=\"punct\">(</span><span data-k=\"name\">point</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"comment\">// ...</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Rectangle</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">    <span data-k=\"property\">position</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"function\">draw</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">,</span> <span data-k=\"property\">z</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">3</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// OK</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">15</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">16</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">rectangle</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Rectangle</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">17</span><span class=\"markdown-code-text\">    <span data-k=\"property\">position</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">,</span> <span data-k=\"property\">z</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">3</span> <span data-k=\"punct\">}</span> <span data-k=\"comment\">// ERROR: stored `Point` has exact layout</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">18</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Transparent types - type aliases - induce a generic in constraint positions (like a function parameter) but are encoded directly in storage positions (like a field in an aggregate).\nThis is primarily such that the common pattern of <code>class Player { status: &quot;running&quot; | &quot;walking&quot; | &quot;idle&quot; }</code> (which is really just a type alias) works as expected without any additional confusing generics.\nUnlike transparent type aliases, interfaces also induce a generic in storage positions (even as both behave like structural types in general):</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Representation</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">interface</span> <span data-k=\"type\">PointLike</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">draw</span><span data-k=\"punct\">(</span><span data-k=\"name\">point</span><span data-k=\"punct\">:</span> <span data-k=\"type\">PointLike</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\">    <span data-k=\"comment\">// ...</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Rectangle</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">    <span data-k=\"property\">start</span><span data-k=\"punct\">:</span> <span data-k=\"type\">PointLike</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\">    <span data-k=\"property\">end</span><span data-k=\"punct\">:</span> <span data-k=\"type\">PointLike</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Desugared, that is roughly:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Representation</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Rectangle</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">TStart</span><span data-k=\"punct\">:</span> <span data-k=\"type\">PointLike</span><span data-k=\"punct\">,</span> <span data-k=\"type\">TEnd</span><span data-k=\"punct\">:</span> <span data-k=\"type\">PointLike</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">start</span><span data-k=\"punct\">:</span> <span data-k=\"type\">TStart</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">end</span><span data-k=\"punct\">:</span> <span data-k=\"type\">TEnd</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Anonymous constraint expressions require a specific type to be filled in at usage sites and thus induce a generic:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Representation</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">newtype</span> <span data-k=\"keyword\">interface</span> <span data-k=\"type\">Writer</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">write</span><span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">uint</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Error</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">interface</span> <span data-k=\"type\">Writer</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">    <span data-k=\"property\">write</span><span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">uint</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Error</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">Writer</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">    <span data-k=\"property\">write</span><span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">uint</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Error</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>For contrast, a function-valued field is still an ordinary representable structural shape, because the field itself has a representation (a function pointer):</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Representation</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">WriterField</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">write</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">usize</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Error</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><p>Structural type annotations still typecheck structurally, and structural value expressions synthesize concrete anonymous shapes when they are used as values.\nHere the annotation checks the object shape, and the object expression supplies the concrete value shape:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Representation</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">}</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"property\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">2</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></code></pre></figure><p>Return positions are also considered storage positions, and the return representation is solved from the function body:</p>\n<ul>\n<li>When all joined return paths produce <em>one</em> concrete type, the return is existential, that is, callers type against the declared transparent type, but the compiled function returns the specific concrete representation at zero cost.</li>\n<li>When the paths join <em>different</em> concrete types and the declared return is a transparent data shape (like a union alias), the return reifies that shape&#39;s concrete layout - for a union alias, the tagged variant layout - just as a stored field would.</li>\n</ul>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Representation</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">Shape</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Rectangle</span> <span data-k=\"punct\">|</span> <span data-k=\"type\">Circle</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// transparent alias</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">foo</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Shape</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">return</span> <span data-k=\"type\">Rectangle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span> <span data-k=\"comment\">// existential: the compiled return type is Rectangle</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">bar</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Shape</span> <span data-k=\"punct\">{</span> <span data-k=\"comment\">// reified: the compiled return type is the Shape variant layout</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"function\">getRandom</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">&gt;</span> <span data-k=\"literal\">4</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">        <span data-k=\"keyword\">return</span> <span data-k=\"type\">Circle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\">        <span data-k=\"keyword\">return</span> <span data-k=\"type\">Rectangle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\">    <span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>A representation change is also exactly what separates a compiled conversion from a plain type-level widening.\nAn implicit conversion reifies as a coercion only when the identity function is not a valid witness for it: injecting a value into a tagged union writes a tag and erasing behind <code>Dynamic&lt;T&gt;</code> builds the fat pointer, while readonly and variance widenings change nothing physical and compile to nothing.\nLiterals never convert at all; a constant materializes directly at its solved type.</p>\n<h2 id=\"dynamic\">Dynamic</h2><p>The default being that structural constraints become hidden generic parameters is <em>generally</em> great for performance in a <code>type</code>-heavy language like TypeScript, and it works especially well because we always compile statically from source.\nHowever, sometimes explicit <em>runtime</em> indirection / erasure is desired, and Destack also provides an intrinsic <code>Dynamic&lt;T&gt;</code> wrapper as the explicit erased runtime value satisfying any dynamic-safe <code>T</code>:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Dynamic</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// just like the function, this Logger is implicitly generic over Writer</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Logger</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">writer</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Writer</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// the Logger above is the same as Logger&lt;T: Writer&gt;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">Logger</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Writer</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"property\">writer</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">11</span><span class=\"markdown-code-text\"><span data-k=\"comment\">// for fixed layout, erase the constraint</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">12</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">LoggerFor</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">13</span><span class=\"markdown-code-text\">    <span data-k=\"property\">writer</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Dynamic</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Writer</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">14</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>For a type <code>T</code> to become concrete (as required by <code>Dynamic&lt;T&gt;</code>), it must have a shape we can actually erase into a value at runtime (the &quot;runtime witness&quot;: we call this property <code>DynamicSafe</code>.\nBasically, the <code>T</code> in <code>Dynamic&lt;T&gt;</code> implies <code>DynamicSafe</code>, which is very similar to Rust&#39;s &quot;object-safe&quot; requirements for <code>dyn T</code>:</p>\n<ul>\n<li>no generic members that introduce new generic parameters</li>\n<li>no index signatures</li>\n<li>no unqualified reference to <code>this</code></li>\n</ul>\n<p>Of course, the <code>Dynamic&lt;T&gt;</code> value <em>itself</em> is always <code>Concrete</code>: erasure is precisely what gives an abstract constraint one fixed sized runtime representation.</p>\n<h2 id=\"layout\">Layout</h2><p>Layout is the concrete storage and ABI shape selected for a representable type under the active target, the default representation being <code>@repr(&quot;destack&quot;)</code>.\nOnly represented types have layout; structural shapes become represented when a representation slot reifies them, while incomplete constraints must be preserved through a generic parameter or erased behind <code>Dynamic&lt;T&gt;</code>.\nThe exact layout of a type can be configured via decorators that constrain its representation as needed, the conventions being very similar to Rust&#39;s:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Decorator</th>\n<th>Meaning</th>\n</tr>\n</thead><tbody><tr>\n<td><code>@repr(&quot;destack&quot;)</code></td>\n<td>Use the native Destack representation.</td>\n</tr>\n<tr>\n<td><code>@repr(&quot;C&quot;)</code></td>\n<td>Use the active target&#39;s C ABI layout.</td>\n</tr>\n<tr>\n<td><code>@repr(&quot;transparent&quot;)</code></td>\n<td>Give a single-field declaration the same ABI representation as its field.</td>\n</tr>\n<tr>\n<td><code>@repr(T)</code></td>\n<td>Use primitive scalar <code>T</code> as an enum backing representation.</td>\n</tr>\n<tr>\n<td><code>@repr({ align: N })</code></td>\n<td>Raise the minimum aggregate alignment to <code>N</code>.</td>\n</tr>\n<tr>\n<td><code>@repr({ packed: true })</code> / <code>@repr({ packed: N })</code></td>\n<td>Lower the maximum field alignment, with <code>true</code> equivalent to <code>1</code>.</td>\n</tr>\n</tbody></table></div><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Layout</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\">@<span data-k=\"function\">repr</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"property\">align</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">64</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">CacheLine</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint64</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\">@<span data-k=\"function\">repr</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;C&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">packed</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">true</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">WireHeader</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\">    <span data-k=\"property\">tag</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\">    <span data-k=\"property\">size</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint32</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">10</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span></code></pre></figure><p>Destack also supports querying parameters of the effective representation during compilation - available as a <a href=\"#static\">static term</a> during inference - for conditional branching and storage:</p>\n<div class=\"markdown-table\" tabindex=\"0\"><table><thead><tr>\n<th>Layout Query</th>\n<th>Result</th>\n</tr>\n</thead><tbody><tr>\n<td><code>sizeOf&lt;T&gt;()</code></td>\n<td>The byte size of <code>T</code> as <code>usize</code>.</td>\n</tr>\n<tr>\n<td><code>alignOf&lt;T&gt;()</code></td>\n<td>The required alignment of <code>T</code> as <code>usize</code>.</td>\n</tr>\n<tr>\n<td><code>strideOf&lt;T&gt;()</code></td>\n<td>The spacing between adjacent array elements of <code>T</code> as <code>usize</code>.</td>\n</tr>\n<tr>\n<td><code>layoutOf&lt;T&gt;()</code></td>\n<td>The reflected <code>size</code>, <code>align</code>, <code>stride</code>, and shape for <code>T</code> as a <code>Layout</code> value.</td>\n</tr>\n</tbody></table></div><p>Layout queries evaluate as type operations: a query over an open or generic type stays symbolic and reduces to its value once its argument becomes concrete.\nInference therefore answers exactly the queries whose inputs it has settled, and comptime evaluation forces the remainder.\nLayout is never stored in the compiler&#39;s program representation; every phase recomputes it on demand from the type and the active target through one shared measure, and code generation derives its structural layout from that same measure.</p>\n<h2 id=\"reflection\">Reflection</h2><p>TypeScript types are - by design - erased at runtime, which means we can&#39;t easily perform runtime type checks or any meaningful reflection.\nDestack supports type reflection both at runtime and at compile time with <code>Type&lt;T&gt;</code> as a normalized view.\nDynamic type expression can be turned into its reflected type with (implicit or explicit) casting to its <code>Type</code> representation:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Reflection</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">struct</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\">    <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\">    <span data-k=\"property\">age</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">5</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">6</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">let</span> <span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span> <span data-k=\"property\">name</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;Alice&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"property\">age</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">30</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">7</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">8</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"type\">UserType</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Type</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>     <span data-k=\"comment\">// implicit cast</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">9</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"type\">UserType</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Type</span><span data-k=\"punct\">.</span><span data-k=\"property\">of</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>      <span data-k=\"comment\">// explicit, same thing</span></span></span></code></pre></figure><p>This also works for generic APIs that operate on types as static values:</p>\n<figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Reflection</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">function</span> <span data-k=\"function\">parse</span><span data-k=\"punct\">&lt;</span><span data-k=\"keyword\">comptime</span> <span data-k=\"type\">T</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Type</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">raw</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span> <span data-k=\"punct\">{</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"punct\">}</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"> </span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">4</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">user</span> <span data-k=\"punct\">=</span> <span data-k=\"function\">parse</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;...&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span></code></pre></figure><figure class=\"markdown-code\"><figcaption><span class=\"markdown-code__title\">Reflection</span><span class=\"markdown-code__format\">.ds</span></figcaption><pre tabindex=\"0\"><code class=\"markdown-code-lines\"><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">1</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">userSize</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"function\">sizeOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">2</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">const</span> <span data-k=\"name\">requestLayout</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">comptime</span> <span data-k=\"function\">layoutOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Request</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Body</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span></span></span><span class=\"markdown-code-line\"><span class=\"markdown-code-gutter\">3</span><span class=\"markdown-code-text\"><span data-k=\"keyword\">type</span> <span data-k=\"type\">InlineBytes</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Concrete</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"function\">sizeOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span></span></span></code></pre></figure>", {  }),
} satisfies DocumentContent;

export default content;

/// Replace build-time asset placeholders with bundled URLs.
function resolveAssets(html: string, assets: Record<string, string>) {
    let resolved = html;

    for (const [placeholder, asset] of Object.entries(assets)) {
        resolved = resolved.replaceAll(placeholder, asset);
    }

    return resolved;
}
